describe('handle', () => {
  const fileUrl = 'https://example.com/file.jpg';
  const s3PresignedUrl = 'https://bucket.s3.amazonaws.com/key?sig=123';
  const s3PublicUrl = 'https://bucket.s3.amazonaws.com/key';
  const airtableBaseId = 'appBase';
  const airtableTableId = 'tblTable';
  const airtableRecordId = 'recRecord';
  const airtableApiKey = 'key123';

  const baseConfig: ConnectorConfig = {
    airtableApiKey,
    airtableBaseId,
    airtableTableId,
    airtableRecordId,
    s3PresignedUrl,
    s3PublicUrl,
    maxRetries: 0,
  };

  const validPayload: TypeformWebhookPayload = {
    event_id: 'evt1',
    event_type: 'form_response',
    form_response: {
      form_id: 'form1',
      token: 'token1',
      submitted_at: '2024-01-01T00:00:00Z',
      answers: [
        {
          type: 'file_url',
          file_url: fileUrl,
          field: { id: 'field1', type: 'file_upload' },
        },
      ],
    },
  };

  it('successfully processes file upload and updates Airtable', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'GET' && req.url === fileUrl) {
        return new Response(new Uint8Array([1, 2, 3]), {
          status: 200,
          headers: { 'Content-Type': 'image/jpeg' },
        });
      }
      if (req.method === 'PUT' && req.url === s3PresignedUrl) {
        return new Response(null, { status: 200 });
      }
      if (req.method === 'PATCH' && req.url.includes('api.airtable.com')) {
        return jsonResponse({
          id: airtableRecordId,
          fields: { Attachment: [{ id: 'att1', url: s3PublicUrl, filename: 'file.jpg' }] },
        });
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const result = await handle(validPayload, { ...baseConfig, fetch });

    expect(result).toEqual({
      airtableRecordId,
      attachmentId: 'att1',
      s3PublicUrl,
    });
    expect(calls).toHaveLength(3);
    expect(calls[0].method).toBe('GET');
    expect(calls[1].method).toBe('PUT');
    expect(calls[2].method).toBe('PATCH');
    expect(calls[2].headers.get('Authorization')).toBe(`Bearer ${airtableApiKey}`);
    expect(calls[2].json).toEqual({
      fields: { Attachment: [{ url: s3PublicUrl }] },
    });
  });

  it('throws when payload missing form_response.answers', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const badPayload = { ...validPayload, form_response: { ...validPayload.form_response, answers: [] } };
    await expect(handle(badPayload, { ...baseConfig, fetch })).rejects.toThrow(
      'Payload missing form_response.answers'
    );
  });

  it('throws when no file_url answer present', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const badPayload = {
      ...validPayload,
      form_response: {
        ...validPayload.form_response,
        answers: [{ type: 'text', field: { id: 'f1', type: 'short_text' } }],
      },
    };
    await expect(handle(badPayload, { ...baseConfig, fetch })).rejects.toThrow(
      'No file_url answer found in payload'
    );
  });

  it('throws when required config missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const incompleteConfig = { ...baseConfig, s3PresignedUrl: '' };
    await expect(handle(validPayload, incompleteConfig)).rejects.toThrow(
      'Missing required config: s3PresignedUrl'
    );
  });

  it('throws on non-2xx from Typeform file download', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ error: 'not found' }, 404));
    await expect(handle(validPayload, { ...baseConfig, fetch })).rejects.toThrow(
      'Typeform file download failed with status 404: Not Found'
    );
  });

  it('throws on non-2xx from S3 presigned upload', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'GET' && req.url === fileUrl) {
        return new Response(new Uint8Array([1]), { status: 200 });
      }
      return jsonResponse({ error: 'forbidden' }, 403);
    });
    await expect(handle(validPayload, { ...baseConfig, fetch })).rejects.toThrow(
      'S3 presigned upload failed with status 403: Forbidden'
    );
    expect(calls).toHaveLength(2);
  });

  it('throws on non-2xx from Airtable update', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'GET' && req.url === fileUrl) {
        return new Response(new Uint8Array([1]), { status: 200 });
      }
      if (req.method === 'PUT' && req.url === s3PresignedUrl) {
        return new Response(null, { status: 200 });
      }
      return jsonResponse({ error: 'unauthorized' }, 401);
    });
    await expect(handle(validPayload, { ...baseConfig, fetch })).rejects.toThrow(
      'Airtable record update failed with status 401: Unauthorized'
    );
    expect(calls).toHaveLength(3);
  });

  it('retries on 429 then succeeds', async () => {
    let attempt = 0;
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'GET' && req.url === fileUrl) {
        return new Response(new Uint8Array([1]), { status: 200 });
      }
      if (req.method === 'PUT' && req.url === s3PresignedUrl) {
        if (attempt++ === 0) {
          return new Response(null, { status: 429, headers: { 'Retry-After': '1' } });
        }
        return new Response(null, { status: 200 });
      }
      return jsonResponse({
        id: airtableRecordId,
        fields: { Attachment: [{ id: 'att1', url: s3PublicUrl, filename: 'file.jpg' }] },
      });
    });

    const result = await handle(validPayload, { ...baseConfig, fetch, maxRetries: 3 });
    expect(result.attachmentId).toBe('att1');
    expect(calls.filter((c) => c.method === 'PUT')).toHaveLength(2);
  });

  it('exhausts retries on persistent 500', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'GET' && req.url === fileUrl) {
        return new Response(new Uint8Array([1]), { status: 200 });
      }
      return new Response(null, { status: 500 });
    });

    await expect(handle(validPayload, { ...baseConfig, fetch, maxRetries: 2 })).rejects.toThrow(
      'S3 presigned upload failed after 2 retries'
    );
    expect(calls.filter((c) => c.method === 'PUT')).toHaveLength(3);
  });
});

