function parseRetryAfter(value: string): number {
  const seconds = parseInt(value, 10);
  if (!isNaN(seconds)) return seconds * 1000;
  const date = new Date(value);
  if (!isNaN(date.getTime())) return Math.max(0, date.getTime() - Date.now());
  return NaN;
}

async function fetchWithRetry(
  fetchFn: typeof fetch,
  url: string,
  init: RequestInit,
  maxRetries: number,
  endpointName: string
): Promise<Response> {
  const baseMs = 1000;
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    const response = await fetchFn(url, init);
    if (response.ok) return response;

    const retryable = response.status === 429 || (response.status >= 500 && response.status < 600);
    if (!retryable || attempt === maxRetries) {
      if (attempt > 0) {
        throw new Error(`${endpointName} failed after ${attempt} retries`);
      }
      throw new Error(`${endpointName} failed with status ${response.status}: ${response.statusText}`);
    }

    let delayMs = baseMs * 2 ** attempt;
    const retryAfter = response.headers.get('Retry-After');
    if (retryAfter) {
      const parsed = parseRetryAfter(retryAfter);
      if (!isNaN(parsed)) delayMs = Math.max(parsed, delayMs);
    }
    await new Promise((resolve) => setTimeout(resolve, delayMs));
  }
  throw new Error(`${endpointName} failed after ${maxRetries} retries`);
}

export async function handle(payload: TypeformWebhookPayload, config: ConnectorConfig): Promise<ConnectorResult> {
  if (!payload.form_response?.answers?.length) {
    throw new Error('Payload missing form_response.answers');
  }
  const fileAnswer = payload.form_response.answers.find(
    (a) => a.type === 'file_url' && a.file_url
  );
  if (!fileAnswer?.file_url) {
    throw new Error('No file_url answer found in payload');
  }

  const requiredConfig: (keyof ConnectorConfig)[] = [
    'airtableApiKey',
    'airtableBaseId',
    'airtableTableId',
    'airtableRecordId',
    's3PresignedUrl',
    's3PublicUrl',
  ];
  for (const key of requiredConfig) {
    if (!config[key]) throw new Error(`Missing required config: ${key}`);
  }

  const fetchFn = config.fetch ?? fetch;
  const fileFetchFn = config.fileFetch ?? fetchFn;
  const maxRetries = config.maxRetries ?? 3;

  const fileResponse = await fetchWithRetry(
    fileFetchFn,
    fileAnswer.file_url,
    { method: 'GET' },
    maxRetries,
    'Typeform file download'
  );
  const fileBlob = await fileResponse.blob();
  const contentType = fileResponse.headers.get('Content-Type') || 'application/octet-stream';

  await fetchWithRetry(
    fetchFn,
    config.s3PresignedUrl,
    {
      method: 'PUT',
      body: fileBlob,
      headers: { 'Content-Type': contentType },
    },
    maxRetries,
    'S3 presigned upload'
  );

  const airtableUrl = `https://api.airtable.com/v0/${config.airtableBaseId}/${config.airtableTableId}/${config.airtableRecordId}`;
  const airtableBody = {
    fields: {
      Attachment: [{ url: config.s3PublicUrl }],
    },
  };

  const airtableResponse = await fetchWithRetry(
    fetchFn,
    airtableUrl,
    {
      method: 'PATCH',
      headers: {
        Authorization: `Bearer ${config.airtableApiKey}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(airtableBody),
    },
    maxRetries,
    'Airtable record update'
  );

  const airtableResult = (await airtableResponse.json()) as {
    id: string;
    fields: { Attachment: Array<{ id: string; url: string; filename: string }> };
  };
  const attachment = airtableResult.fields.Attachment?.[0];
  if (!attachment?.id) throw new Error('Airtable response missing attachment id');

  return {
    airtableRecordId: airtableResult.id,
    attachmentId: attachment.id,
    s3PublicUrl: config.s3PublicUrl,
  };
}

